import{_ as a,o,c as s,ag as r}from"./chunks/framework.CrXGS008.js";const m=JSON.parse('{"title":"Framework personalizado","description":"","frontmatter":{},"headers":[],"relativePath":"pt/bridge/custom.md","filePath":"pt/bridge/custom.md"}'),i={name:"pt/bridge/custom.md"};function t(d,e,c,n,l,p){return o(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="framework-personalizado" tabindex="-1">Framework personalizado <a class="header-anchor" href="#framework-personalizado" aria-label="Permalink to &quot;Framework personalizado&quot;">​</a></h1><p>Usa um framework que a bridge não suporta, ou um framework muito modificado? Ligue-o por si: todos os scripts Nayretis passam a usá-lo.</p><p>O ficheiro <code>nay_lib/bridge/custom.lua</code> vem legível, fora do escrow da Cfx. Contém duas tabelas, uma para o servidor e outra para o cliente, com todas as funções de que os scripts precisam: ler o jogador e a respetiva profissão, dinheiro, itens, notificações. Cada função está documentada no ficheiro com os seus argumentos e os valores que deve devolver.</p><h2 id="passos" tabindex="-1">Passos <a class="header-anchor" href="#passos" aria-label="Permalink to &quot;Passos&quot;">​</a></h2><ol><li><p>Abra <code>nay_lib/bridge/custom.lua</code> e implemente todas as funções das tabelas do servidor e do cliente com os exports ou eventos do seu framework.</p></li><li><p>No <code>server.cfg</code>, force o adaptador personalizado:</p><div class="language-cfg vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cfg</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>setr nay:framework &quot;custom&quot;</span></span></code></pre></div></li><li><p>Reinicie o servidor. O ficheiro é lido por todos os recursos que usam o <code>nay_lib</code>, por isso reinicie-os todos depois de qualquer alteração.</p></li></ol><p>A consola confirma-o no arranque: <code>Bridge ready: framework=custom ...</code>.</p><h2 id="o-que-a-bridge-ja-faz-por-si" tabindex="-1">O que a bridge já faz por si <a class="header-anchor" href="#o-que-a-bridge-ja-faz-por-si" aria-label="Permalink to &quot;O que a bridge já faz por si&quot;">​</a></h2><p>Só tem de comunicar com o seu framework. A própria bridge:</p><ul><li>valida os montantes e as contas (<code>cash</code> e <code>bank</code>, valores inteiros positivos);</li><li>verifica o saldo antes de retirar dinheiro e a quantidade antes de retirar itens;</li><li>avisa os scripts quando um jogador se desliga.</li></ul><p>Precisa de ajuda? Abra uma publicação em <code>#support</code> no <a href="https://discord.gg/HqNyFsDBmw" target="_blank" rel="noreferrer">Discord da Nayretis</a>.</p>',10)])])}const f=a(i,[["render",t]]);export{m as __pageData,f as default};
